32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"monaradi\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:58:\"http://www.ar-wp.com/forums/topic/12559/page/2/#post-16130\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:65:\"رداً على: القائمة المنسدلة الجانبية\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:58:\"http://www.ar-wp.com/forums/topic/12559/page/2/#post-16130\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 23 Sep 2013 23:53:52 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:26127:\"\n						\n						<div id=\"bbpq-content-wrapper-16130\"><p> السلام عليكم </p>\n<p>أخي mas ، جزاك الله خير</p>\n<p>هذا هو ملف style.css:</p>\n<pre class=\"brush: plain; title: ; notranslate\" title=\"\">/*\nTheme Name: Twenty Ten\nTheme URI: http://wordpress.org/themes/twentyten\nDescription: The 2010 theme for WordPress is stylish, customizable, simple, and readable -- make it yours with a custom menu, header image, and background. Twenty Ten supports six widgetized areas (two in the sidebar, four in the footer) and featured images (thumbnails for gallery posts and custom header images for posts and pages). It includes stylesheets for print and the admin Visual Editor, special styles for posts in the &quot;Asides&quot; and &quot;Gallery&quot; categories, and has an optional one-column page template that removes the sidebar.\nAuthor: the WordPress team\nAuthor URI: http://wordpress.org/\nVersion: 1.6\nLicense: GNU General Public License v2 or later\nLicense URI: http://www.gnu.org/licenses/gpl-2.0.html\nTags: black, blue, white, two-columns, fixed-width, custom-header, custom-background, threaded-comments, sticky-post, translation-ready, microformats, rtl-language-support, editor-style, custom-menu, flexible-header\nText Domain: twentyten\n*/\n\n\n/* =Reset default browser CSS. Based on work by Eric Meyer: http://meyerweb.com/eric/tools/css/reset/index.html\n-------------------------------------------------------------- */\n\nhtml, body, div, span, applet, object, iframe,\nh1, h2, h3, h4, h5, h6, p, blockquote, pre,\na, abbr, acronym, address, big, cite, code,\ndel, dfn, em, font, img, ins, kbd, q, s, samp,\nsmall, strike, strong, sub, sup, tt, var,\nb, u, i, center,\ndl, dt, dd, ol, ul, li,\nfieldset, form, label, legend,\ntable, caption, tbody, tfoot, thead, tr, th, td {\n	background: transparent;\n	border: 0;\n	margin: 0;\n	padding: 0;\n	vertical-align: baseline;\n}\nbody {\n	line-height: 1;\n}\nh1, h2, h3, h4, h5, h6 {\n	clear: both;\n	font-weight: normal;\n}\nol, ul {\n	list-style: none;\n}\nblockquote {\n	quotes: none;\n}\nblockquote:before, blockquote:after {\n	content: \'\';\n	content: none;\n}\ndel {\n	text-decoration: line-through;\n}\n/* tables still need \'cellspacing=&quot;0&quot;\' in the markup */\ntable {\n	border-collapse: collapse;\n	border-spacing: 0;\n}\na img {\n	border: none;\n}\n\n/* =Layout\n-------------------------------------------------------------- */\n\n/*\nLAYOUT: Two columns\nDESCRIPTION: Two-column fixed layout with one sidebar right of content\n*/\n\n#container {\n	float: left;\n	margin: 0 -240px 0 0;\n	width: 100%;\n}\n#content {\n	margin: 0 280px 0 20px;\n}\n#primary,\n#secondary {\n	float: right;\n	overflow: hidden;\n	width: 220px;\n}\n#secondary {\n	clear: right;\n}\n#footer {\n	clear: both;\n	width: 100%;\n}\n\n/*\nLAYOUT: One column, no sidebar\nDESCRIPTION: One centered column with no sidebar\n*/\n\n.one-column #content {\n	margin: 0 auto;\n	width: 640px;\n}\n\n/*\nLAYOUT: Full width, no sidebar\nDESCRIPTION: Full width content with no sidebar; used for attachment pages\n*/\n\n.single-attachment #content {\n	margin: 0 auto;\n	width: 900px;\n}\n\n\n/* =Fonts\n-------------------------------------------------------------- */\nbody,\ninput,\ntextarea,\n.page-title span,\n.pingback a.url {\n	font-family: Georgia, &quot;Bitstream Charter&quot;, serif;\n}\nh3#comments-title,\nh3#reply-title,\n#access .menu,\n#access div.menu ul,\n#cancel-comment-reply-link,\n.form-allowed-tags,\n#site-info,\n#site-title,\n#wp-calendar,\n.comment-meta,\n.comment-body tr th,\n.comment-body thead th,\n.entry-content label,\n.entry-content tr th,\n.entry-content thead th,\n.entry-meta,\n.entry-title,\n.entry-utility,\n#respond label,\n.navigation,\n.page-title,\n.pingback p,\n.reply,\n.widget-title,\n.wp-caption-text {\n	font-family: &quot;Helvetica Neue&quot;, Arial, Helvetica, &quot;Nimbus Sans L&quot;, sans-serif;\n}\ninput[type=&quot;submit&quot;] {\n	font-family: &quot;Helvetica Neue&quot;, Arial, Helvetica, &quot;Nimbus Sans L&quot;, sans-serif;\n}\npre {\n	font-family: &quot;Courier 10 Pitch&quot;, Courier, monospace;\n}\ncode {\n	font-family: Monaco, Consolas, &quot;Andale Mono&quot;, &quot;DejaVu Sans Mono&quot;, monospace;\n}\n\n\n/* =Structure\n-------------------------------------------------------------- */\n\n/* The main theme structure */\n#access .menu-header,\ndiv.menu,\n#colophon,\n#branding,\n#main,\n#wrapper {\n	margin: 0 auto;\n	width: 940px;\n}\n#wrapper {\n	background: #fff;\n	margin-top: 20px;\n	padding: 0 20px;\n}\n\n/* Structure the footer area */\n#footer-widget-area {\n	overflow: hidden;\n}\n#footer-widget-area .widget-area {\n	float: left;\n	margin-right: 20px;\n	width: 220px;\n}\n#footer-widget-area #fourth {\n	margin-right: 0;\n}\n#site-info {\n	float: left;\n	font-size: 14px;\n	font-weight: bold;\n	width: 700px;\n}\n#site-generator {\n	float: right;\n	width: 220px;\n}\n\n\n/* =Global Elements\n-------------------------------------------------------------- */\n\n/* Main global \'theme\' and typographic styles */\nbody {\n	background: #f1f1f1;\n}\nbody,\ninput,\ntextarea {\n	color: #666;\n	font-size: 12px;\n	line-height: 18px;\n}\nhr {\n	background-color: #e7e7e7;\n	border: 0;\n	clear: both;\n	height: 1px;\n	margin-bottom: 18px;\n}\n\n/* Text elements */\np {\n	margin-bottom: 18px;\n}\nul {\n	list-style: square;\n	margin: 0 0 18px 1.5em;\n}\nol {\n	list-style: decimal;\n	margin: 0 0 18px 1.5em;\n}\nol ol {\n	list-style: upper-alpha;\n}\nol ol ol {\n	list-style: lower-roman;\n}\nol ol ol ol {\n	list-style: lower-alpha;\n}\nul ul,\nol ol,\nul ol,\nol ul {\n	margin-bottom: 0;\n}\ndl {\n	margin: 0 0 24px 0;\n}\ndt {\n	font-weight: bold;\n}\ndd {\n	margin-bottom: 18px;\n}\nstrong {\n	font-weight: bold;\n}\ncite,\nem,\ni {\n	font-style: italic;\n}\nbig {\n	font-size: 131.25%;\n}\nins {\n	background: #ffc;\n	text-decoration: none;\n}\nblockquote {\n	font-style: italic;\n	padding: 0 3em;\n}\nblockquote cite,\nblockquote em,\nblockquote i {\n	font-style: normal;\n}\npre {\n	background: #f7f7f7;\n	color: #222;\n	line-height: 18px;\n	margin-bottom: 18px;\n	overflow: auto;\n	padding: 1.5em;\n}\nabbr,\nacronym {\n	border-bottom: 1px dotted #666;\n	cursor: help;\n}\nsup,\nsub {\n	height: 0;\n	line-height: 1;\n	position: relative;\n	vertical-align: baseline;\n}\nsup {\n	bottom: 1ex;\n}\nsub {\n	top: .5ex;\n}\nsmall {\n	font-size: smaller;\n}\ninput[type=&quot;text&quot;],\ninput[type=&quot;password&quot;],\ninput[type=&quot;email&quot;],\ninput[type=&quot;url&quot;],\ninput[type=&quot;number&quot;],\ntextarea {\n	background: #f9f9f9;\n	border: 1px solid #ccc;\n	box-shadow: inset 1px 1px 1px rgba(0,0,0,0.1);\n	-moz-box-shadow: inset 1px 1px 1px rgba(0,0,0,0.1);\n	-webkit-box-shadow: inset 1px 1px 1px rgba(0,0,0,0.1);\n	padding: 2px;\n}\na:link {\n	color: #0066cc;\n}\na:visited {\n	color: #743399;\n}\na:active,\na:hover {\n	color: #ff4b33;\n}\n\n/* Text meant only for screen readers */\n.screen-reader-text {\n	position: absolute;\n	left: -9000px;\n}\n\n\n/* =Header\n-------------------------------------------------------------- */\n\n#header {\n	padding: 30px 0 0 0;\n}\n#site-title {\n	float: left;\n	font-size: 30px;\n	line-height: 36px;\n	margin: 0 0 18px 0;\n	width: 700px;\n}\n#site-title a {\n	color: #000;\n	font-weight: bold;\n	text-decoration: none;\n}\n#site-description {\n	clear: right;\n	float: right;\n	font-style: italic;\n	margin: 15px 0 18px 0;\n	width: 220px;\n}\n\n/* This is the custom header image */\n#branding img {\n	border-top: 4px solid #000;\n	border-bottom: 1px solid #000;\n	display: block;\n	float: left;\n}\n\n\n/* =Menu\n-------------------------------------------------------------- */\n\n#access {\n	background: #000;\n	display: block;\n	float: left;\n	margin: 0 auto;\n	width: 940px;\n}\n#access .menu-header,\ndiv.menu {\n	font-size: 13px;\n	margin-left: 12px;\n	width: 928px;\n}\n#access .menu-header ul,\ndiv.menu ul {\n	list-style: none;\n	margin: 0;\n}\n#access .menu-header li,\ndiv.menu li {\n	float: left;\n	position: relative;\n}\n#access a {\n	color: #aaa;\n	display: block;\n	line-height: 38px;\n	padding: 0 10px;\n	text-decoration: none;\n}\n#access ul ul {\n	box-shadow: 0px 3px 3px rgba(0,0,0,0.2);\n	-moz-box-shadow: 0px 3px 3px rgba(0,0,0,0.2);\n	-webkit-box-shadow: 0px 3px 3px rgba(0,0,0,0.2);\n	display: none;\n	position: absolute;\n	top: 38px;\n	left: 0;\n	float: left;\n	width: 180px;\n	z-index: 99999;\n}\n#access ul ul li {\n	min-width: 180px;\n}\n#access ul ul ul {\n	left: 100%;\n	top: 0;\n}\n#access ul ul a {\n	background: #333;\n	line-height: 1em;\n	padding: 10px;\n	width: 160px;\n	height: auto;\n}\n#access li:hover &gt; a,\n#access ul ul :hover &gt; a {\n	background: #333;\n	color: #fff;\n}\n#access ul li:hover &gt; ul {\n	display: block;\n}\n#access ul li.current_page_item &gt; a,\n#access ul li.current_page_ancestor &gt; a,\n#access ul li.current-menu-ancestor &gt; a,\n#access ul li.current-menu-item &gt; a,\n#access ul li.current-menu-parent &gt; a {\n	color: #fff;\n}\n* html #access ul li.current_page_item a,\n* html #access ul li.current_page_ancestor a,\n* html #access ul li.current-menu-ancestor a,\n* html #access ul li.current-menu-item a,\n* html #access ul li.current-menu-parent a,\n* html #access ul li a:hover {\n	color: #fff;\n}\n\n\n/* =Content\n-------------------------------------------------------------- */\n\n#main {\n	clear: both;\n	overflow: hidden;\n	padding: 40px 0 0 0;\n}\n#content {\n	margin-bottom: 36px;\n}\n#content,\n#content input,\n#content textarea {\n	color: #333;\n	font-size: 16px;\n	line-height: 24px;\n}\n#content p,\n#content ul,\n#content ol,\n#content dd,\n#content pre,\n#content hr {\n	margin-bottom: 24px;\n}\n#content ul ul,\n#content ol ol,\n#content ul ol,\n#content ol ul {\n	margin-bottom: 0;\n}\n#content pre,\n#content kbd,\n#content tt,\n#content var {\n	font-size: 15px;\n	line-height: 21px;\n}\n#content code {\n	font-size: 13px;\n}\n#content dt,\n#content th {\n	color: #000;\n}\n#content h1,\n#content h2,\n#content h3,\n#content h4,\n#content h5,\n#content h6 {\n	color: #000;\n	line-height: 1.5em;\n	margin: 0 0 20px 0;\n}\n#content table {\n	border: 1px solid #e7e7e7;\n	margin: 0 -1px 24px 0;\n	text-align: left;\n	width: 100%;\n}\n#content tr th,\n#content thead th {\n	color: #777;\n	font-size: 12px;\n	font-weight: bold;\n	line-height: 18px;\n	padding: 9px 24px;\n}\n#content tr td {\n	border-top: 1px solid #e7e7e7;\n	padding: 6px 24px;\n}\n#content tr.odd td {\n	background: #f2f7fc;\n}\n.hentry {\n	margin: 0 0 48px 0;\n}\n.home .sticky {\n	background: #f2f7fc;\n	border-top: 4px solid #000;\n	margin-left: -20px;\n	margin-right: -20px;\n	padding: 18px 20px;\n}\n.single .hentry {\n	margin: 0 0 36px 0;\n}\n.page-title {\n	color: #000;\n	font-size: 14px;\n	font-weight: bold;\n	margin: 0 0 36px 0;\n}\n.page-title span {\n	color: #333;\n	font-size: 16px;\n	font-style: italic;\n	font-weight: normal;\n}\n.page-title a:link,\n.page-title a:visited {\n	color: #777;\n	text-decoration: none;\n}\n.page-title a:active,\n.page-title a:hover {\n	color: #ff4b33;\n}\n#content .entry-title {\n	color: #000;\n	font-size: 21px;\n	font-weight: bold;\n	line-height: 1.3em;\n	margin-bottom: 0;\n}\n.entry-title a:link,\n.entry-title a:visited {\n	color: #000;\n	text-decoration: none;\n}\n.entry-title a:active,\n.entry-title a:hover {\n	color: #ff4b33;\n}\n.entry-meta {\n	color: #777;\n	font-size: 12px;\n}\n.entry-meta abbr,\n.entry-utility abbr {\n	border: none;\n}\n.entry-meta abbr:hover,\n.entry-utility abbr:hover {\n	border-bottom: 1px dotted #666;\n}\n.entry-content,\n.entry-summary {\n	clear: both;\n	padding: 12px 0 0 0;\n}\n#content .entry-summary p:last-child {\n	margin-bottom: 12px;\n}\n.entry-content fieldset {\n	border: 1px solid #e7e7e7;\n	margin: 0 0 24px 0;\n	padding: 24px;\n}\n.entry-content fieldset legend {\n	background: #fff;\n	color: #000;\n	font-weight: bold;\n	padding: 0 24px;\n}\n.entry-content input {\n	margin: 0 0 24px 0;\n}\n.entry-content input.file,\n.entry-content input.button {\n	margin-right: 24px;\n}\n.entry-content label {\n	color: #777;\n	font-size: 12px;\n}\n.entry-content select {\n	margin: 0 0 24px 0;\n}\n.entry-content sup,\n.entry-content sub {\n	font-size: 10px;\n}\n.entry-content blockquote.left {\n	float: left;\n	margin-left: 0;\n	margin-right: 24px;\n	text-align: right;\n	width: 33%;\n}\n.entry-content blockquote.right {\n	float: right;\n	margin-left: 24px;\n	margin-right: 0;\n	text-align: left;\n	width: 33%;\n}\n.page-link {\n	clear: both;\n	color: #000;\n	font-weight: bold;\n	line-height: 48px;\n	word-spacing: 0.5em;\n}\n.page-link a:link,\n.page-link a:visited {\n	background: #f1f1f1;\n	color: #333;\n	font-weight: normal;\n	padding: 0.5em 0.75em;\n	text-decoration: none;\n}\n.home .sticky .page-link a {\n	background: #d9e8f7;\n}\n.page-link a:active,\n.page-link a:hover {\n	color: #ff4b33;\n}\nbody.page .edit-link {\n	clear: both;\n	display: block;\n}\n#entry-author-info {\n	background: #f2f7fc;\n	border-top: 4px solid #000;\n	clear: both;\n	font-size: 14px;\n	line-height: 20px;\n	margin: 24px 0;\n	overflow: hidden;\n	padding: 18px 20px;\n}\n#entry-author-info #author-avatar {\n	background: #fff;\n	border: 1px solid #e7e7e7;\n	float: left;\n	height: 60px;\n	margin: 0 -104px 0 0;\n	padding: 11px;\n}\n#entry-author-info #author-description {\n	float: left;\n	margin: 0 0 0 104px;\n}\n#entry-author-info h2 {\n	color: #000;\n	font-size: 100%;\n	font-weight: bold;\n	margin-bottom: 0;\n}\n.entry-utility {\n	clear: both;\n	color: #777;\n	font-size: 12px;\n	line-height: 18px;\n}\n.entry-meta a,\n.entry-utility a {\n	color: #777;\n}\n.entry-meta a:hover,\n.entry-utility a:hover {\n	color: #ff4b33;\n}\n#content .video-player {\n	padding: 0;\n}\n\n\n/* =Asides\n-------------------------------------------------------------- */\n\n.home #content .format-aside p,\n.home #content .category-asides p {\n	font-size: 14px;\n	line-height: 20px;\n	margin-bottom: 10px;\n	margin-top: 0;\n}\n.home .hentry.format-aside,\n.home .hentry.category-asides {\n	padding: 0;\n}\n.home #content .format-aside .entry-content,\n.home #content .category-asides .entry-content {\n	padding-top: 0;\n}\n\n\n/* =Gallery listing\n-------------------------------------------------------------- */\n\n.format-gallery .size-thumbnail img,\n.category-gallery .size-thumbnail img {\n	border: 10px solid #f1f1f1;\n	margin-bottom: 0;\n}\n.format-gallery .gallery-thumb,\n.category-gallery .gallery-thumb {\n	float: left;\n	margin-right: 20px;\n	margin-top: -4px;\n}\n.home #content .format-gallery .entry-utility,\n.home #content .category-gallery .entry-utility {\n	padding-top: 4px;\n}\n\n\n/* =Attachment pages\n-------------------------------------------------------------- */\n\n.attachment .entry-content .entry-caption {\n	font-size: 140%;\n	margin-top: 24px;\n}\n.attachment .entry-content .nav-previous a:before {\n	content: \'\\2190&amp;#092;&amp;#048;0a0\';\n}\n.attachment .entry-content .nav-next a:after {\n	content: \'&amp;#092;&amp;#048;0a0\\2192\';\n}\n\n\n/* =Images\n-------------------------------------------------------------- */\n\n/*\nResize images to fit the main content area.\n- Applies only to images uploaded via WordPress by targeting size-* classes.\n- Other images will be left alone. Use &quot;size-auto&quot; class to apply to other images.\n*/\nimg.size-auto,\nimg.size-full,\nimg.size-large,\nimg.size-medium,\n.attachment img,\n.widget-container img {\n	max-width: 100%; /* When images are too wide for containing element, force them to fit. */\n	height: auto; /* Override height to match resized width for correct aspect ratio. */\n}\n.alignleft,\nimg.alignleft {\n	display: inline;\n	float: left;\n	margin-right: 24px;\n	margin-top: 4px;\n}\n.alignright,\nimg.alignright {\n	display: inline;\n	float: right;\n	margin-left: 24px;\n	margin-top: 4px;\n}\n.aligncenter,\nimg.aligncenter {\n	clear: both;\n	display: block;\n	margin-left: auto;\n	margin-right: auto;\n}\nimg.alignleft,\nimg.alignright,\nimg.aligncenter {\n	margin-bottom: 12px;\n}\n.wp-caption {\n	background: #f1f1f1;\n	line-height: 18px;\n	margin-bottom: 20px;\n	max-width: 632px !important; /* prevent too-wide images from breaking layout */\n	padding: 4px;\n	text-align: center;\n}\n.wp-caption img {\n	margin: 5px 5px 0;\n	max-width: 622px; /* caption width - 10px */\n}\n.wp-caption p.wp-caption-text {\n	color: #777;\n	font-size: 12px;\n	margin: 5px;\n}\n.wp-smiley {\n	margin: 0;\n}\n.gallery {\n	margin: 0 auto 18px;\n}\n.gallery .gallery-item {\n	float: left;\n	margin-top: 0;\n	text-align: center;\n	width: 33%;\n}\n.gallery-columns-2 .gallery-item {\n	width: 50%;\n}\n.gallery-columns-4 .gallery-item {\n	width: 25%;\n}\n.gallery img {\n	border: 2px solid #cfcfcf;\n}\n.gallery-columns-2 .attachment-medium {\n	max-width: 92%;\n	height: auto;\n}\n.gallery-columns-4 .attachment-thumbnail {\n	max-width: 84%;\n	height: auto;\n}\n.gallery .gallery-caption {\n	color: #777;\n	font-size: 12px;\n	margin: 0 0 12px;\n}\n.gallery dl {\n	margin: 0;\n}\n.gallery img {\n	border: 10px solid #f1f1f1;\n}\n.gallery br+br {\n	display: none;\n}\n#content .attachment img {/* single attachment images should be centered */\n	display: block;\n	margin: 0 auto;\n}\n\n\n/* =Navigation\n-------------------------------------------------------------- */\n\n.navigation {\n	color: #777;\n	font-size: 12px;\n	line-height: 18px;\n	overflow: hidden;\n}\n.navigation a:link,\n.navigation a:visited {\n	color: #777;\n	text-decoration: none;\n}\n.navigation a:active,\n.navigation a:hover {\n	color: #ff4b33;\n}\n.nav-previous {\n	float: left;\n	width: 50%;\n}\n.nav-next {\n	float: right;\n	text-align: right;\n	width: 50%;\n}\n#nav-above {\n	margin: 0 0 18px 0;\n}\n#nav-above {\n	display: none;\n}\n.paged #nav-above,\n.single #nav-above {\n	display: block;\n}\n#nav-below {\n	margin: -18px 0 0 0;\n}\n\n\n/* =Comments\n-------------------------------------------------------------- */\n#comments {\n	clear: both;\n}\n#comments .navigation {\n	padding: 0 0 18px 0;\n}\nh3#comments-title,\nh3#reply-title {\n	color: #000;\n	font-size: 20px;\n	font-weight: bold;\n	margin-bottom: 0;\n}\nh3#comments-title {\n	padding: 24px 0;\n}\n.commentlist {\n	list-style: none;\n	margin: 0;\n}\n.commentlist li.comment {\n	border-bottom: 1px solid #e7e7e7;\n	line-height: 24px;\n	margin: 0 0 24px 0;\n	padding: 0 0 0 56px;\n	position: relative;\n}\n.commentlist li:last-child {\n	border-bottom: none;\n	margin-bottom: 0;\n}\n#comments .comment-body ul,\n#comments .comment-body ol {\n	margin-bottom: 18px;\n}\n#comments .comment-body p:last-child {\n	margin-bottom: 6px;\n}\n#comments .comment-body blockquote p:last-child {\n	margin-bottom: 24px;\n}\n.commentlist ol {\n	list-style: decimal;\n}\n.commentlist .avatar {\n	position: absolute;\n	top: 4px;\n	left: 0;\n}\n.comment-author {\n}\n.comment-author cite {\n	color: #000;\n	font-style: normal;\n	font-weight: bold;\n}\n.comment-author .says {\n	font-style: italic;\n}\n.comment-meta {\n	font-size: 12px;\n	margin: 0 0 18px 0;\n}\n.comment-meta a:link,\n.comment-meta a:visited {\n	color: #777;\n	text-decoration: none;\n}\n.comment-meta a:active,\n.comment-meta a:hover {\n	color: #ff4b33;\n}\n.commentlist .even {\n}\n.commentlist .bypostauthor {\n}\n.reply {\n	font-size: 12px;\n	padding: 0 0 24px 0;\n}\n.reply a,\na.comment-edit-link {\n	color: #777;\n}\n.reply a:hover,\na.comment-edit-link:hover {\n	color: #ff4b33;\n}\n.commentlist .children {\n	list-style: none;\n	margin: 0;\n}\n.commentlist .children li {\n	border: none;\n	margin: 0;\n}\n.nopassword,\n.nocomments {\n	display: none;\n}\n#comments .pingback {\n	border-bottom: 1px solid #e7e7e7;\n	margin-bottom: 18px;\n	padding-bottom: 18px;\n}\n.commentlist li.comment+li.pingback {\n	margin-top: -6px;\n}\n#comments .pingback p {\n	color: #777;\n	display: block;\n	font-size: 12px;\n	line-height: 18px;\n	margin: 0;\n}\n#comments .pingback .url {\n	font-size: 13px;\n	font-style: italic;\n}\n\n/* Comments form */\ninput[type=&quot;submit&quot;] {\n	color: #333;\n}\n#respond {\n	border-top: 1px solid #e7e7e7;\n	margin: 24px 0;\n	overflow: hidden;\n	position: relative;\n}\n#respond p {\n	margin: 0;\n}\n#respond .comment-notes {\n	margin-bottom: 1em;\n}\n.form-allowed-tags {\n	line-height: 1em;\n}\n.children #respond {\n	margin: 0 48px 0 0;\n}\nh3#reply-title {\n	margin: 18px 0;\n}\n#comments-list #respond {\n	margin: 0 0 18px 0;\n}\n#comments-list ul #respond {\n	margin: 0;\n}\n#cancel-comment-reply-link {\n	font-size: 12px;\n	font-weight: normal;\n	line-height: 18px;\n}\n#respond .required {\n	color: #ff4b33;\n	font-weight: bold;\n}\n#respond label {\n	color: #777;\n	font-size: 12px;\n}\n#respond input {\n	margin: 0 0 9px;\n	width: 98%;\n}\n#respond textarea {\n	width: 98%;\n}\n#respond .form-allowed-tags {\n	color: #777;\n	font-size: 12px;\n	line-height: 18px;\n}\n#respond .form-allowed-tags code {\n	font-size: 11px;\n}\n#respond .form-submit {\n	margin: 12px 0;\n}\n#respond .form-submit input {\n	font-size: 14px;\n	width: auto;\n}\n\n\n/* =Widget Areas\n-------------------------------------------------------------- */\n\n.widget-area ul {\n	list-style: none;\n	margin-left: 0;\n}\n.widget-area ul ul {\n	list-style: square;\n	margin-left: 1.3em;\n}\n.widget-area select {\n	max-width: 100%;\n}\n.widget_search #s {/* This keeps the search inputs in line */\n	width: 60%;\n}\n.widget_search label {\n	display: none;\n}\n.widget-container {\n	word-wrap: break-word;\n	-webkit-hyphens: auto;\n	-moz-hyphens: auto;\n	hyphens: auto;\n	margin: 0 0 18px 0;\n}\n.widget-container .wp-caption img {\n	margin: auto;\n}\n.widget-title {\n	color: #222;\n	font-weight: bold;\n}\n.widget-area a:link,\n.widget-area a:visited {\n	text-decoration: none;\n}\n.widget-area a:active,\n.widget-area a:hover {\n	text-decoration: underline;\n}\n.widget-area .entry-meta {\n	font-size: 11px;\n}\n#wp_tag_cloud div {\n	line-height: 1.6em;\n}\n#wp-calendar {\n	width: 100%;\n}\n#wp-calendar caption {\n	color: #222;\n	font-size: 14px;\n	font-weight: bold;\n	padding-bottom: 4px;\n	text-align: left;\n}\n#wp-calendar thead {\n	font-size: 11px;\n}\n#wp-calendar thead th {\n}\n#wp-calendar tbody {\n	color: #aaa;\n}\n#wp-calendar tbody td {\n	background: #f5f5f5;\n	border: 1px solid #fff;\n	padding: 3px 0 2px;\n	text-align: center;\n}\n#wp-calendar tbody .pad {\n	background: none;\n}\n#wp-calendar tfoot #next {\n	text-align: right;\n}\n.widget_rss a.rsswidget {\n	color: #000;\n}\n.widget_rss a.rsswidget:hover {\n	color: #ff4b33;\n}\n.widget_rss .widget-title img {\n	width: 11px;\n	height: 11px;\n}\n\n/* Main sidebars */\n#main .widget-area ul {\n	margin-left: 0;\n	padding: 0 20px 0 0;\n}\n#main .widget-area ul ul {\n	border: none;\n	margin-left: 1.3em;\n	padding: 0;\n}\n#primary {\n}\n#secondary {\n}\n\n/* Footer widget areas */\n#footer-widget-area {\n}\n\n\n/* =Footer\n-------------------------------------------------------------- */\n\n#footer {\n	margin-bottom: 20px;\n}\n#colophon {\n	border-top: 4px solid #000;\n	margin-top: -4px;\n	overflow: hidden;\n	padding: 18px 0;\n}\n#site-info {\n	font-weight: bold;\n}\n#site-info a {\n	color: #000;\n	text-decoration: none;\n}\n#site-generator {\n	font-style: italic;\n	position: relative;\n}\n#site-generator a {\n	background: url(images/wordpress.png) center left no-repeat;\n	color: #666;\n	display: inline-block;\n	line-height: 16px;\n	padding-left: 20px;\n	text-decoration: none;\n}\n#site-generator a:hover {\n	text-decoration: underline;\n}\nimg#wpstats {\n	display: block;\n	margin: 0 auto 10px;\n}\n\n\n/* =Mobile Safari ( iPad, iPhone and iPod Touch )\n-------------------------------------------------------------- */\n\npre {\n	-webkit-text-size-adjust: 140%;\n}\ncode {\n	-webkit-text-size-adjust: 160%;\n}\n#access,\n.entry-meta,\n.entry-utility,\n.navigation,\n.widget-area {\n	-webkit-text-size-adjust: 120%;\n}\n#site-description {\n	-webkit-text-size-adjust: none;\n}\n\n\n/* =Print Style\n-------------------------------------------------------------- */\n\n@media print {\n	body {\n		background: none !important;\n	}\n	#wrapper {\n		clear: both !important;\n		display: block !important;\n		float: none !important;\n		position: relative !important;\n	}\n	#header {\n		border-bottom: 2pt solid #000;\n		padding-bottom: 18pt;\n	}\n	#colophon {\n		border-top: 2pt solid #000;\n	}\n	#site-title,\n	#site-description {\n		float: none;\n		line-height: 1.4em;\n		margin: 0;\n		padding: 0;\n	}\n	#site-title {\n		font-size: 13pt;\n	}\n	.entry-content {\n		font-size: 14pt;\n		line-height: 1.6em;\n	}\n	.entry-title {\n		font-size: 21pt;\n	}\n	#access,\n	#branding img,\n	#respond,\n	.comment-edit-link,\n	.edit-link,\n	.navigation,\n	.page-link,\n	.widget-area {\n		display: none !important;\n	}\n	#container,\n	#header,\n	#footer {\n		margin: 0;\n		width: 100%;\n	}\n	#content,\n	.one-column #content {\n		margin: 24pt 0 0;\n		width: 100%;\n	}\n	.wp-caption p {\n		font-size: 11pt;\n	}\n	#site-info,\n	#site-generator {\n		float: none;\n		width: auto;\n	}\n	#colophon {\n		width: auto;\n	}\n	img#wpstats {\n		display: none;\n	}\n	#site-generator a {\n		margin: 0;\n		padding: 0;\n	}\n	#entry-author-info {\n		border: 1px solid #e7e7e7;\n	}\n	#main {\n		display: inline;\n	}\n	.home .sticky {\n		border: none;\n	}\n}</pre>\n<p>وهذا هو ملف  sidebar.php:</p>\n<pre class=\"brush: plain; title: ; notranslate\" title=\"\">&lt;?php\n/**\n * The Sidebar containing the primary and secondary widget areas.\n *\n * @package WordPress\n * @subpackage Twenty_Ten\n * @since Twenty Ten 1.0\n */\n?&gt;\n\n		&lt;div id=&quot;primary&quot; class=&quot;widget-area&quot; role=&quot;complementary&quot;&gt;\n			&lt;ul class=&quot;xoxo&quot;&gt;\n\n&lt;?php\n	/* When we call the dynamic_sidebar() function, it\'ll spit out\n	 * the widgets for that widget area. If it instead returns false,\n	 * then the sidebar simply doesn\'t exist, so we\'ll hard-code in\n	 * some default sidebar stuff just in case.\n	 */\n	if ( ! dynamic_sidebar( \'primary-widget-area\' ) ) : ?&gt;\n\n			&lt;li id=&quot;search&quot; class=&quot;widget-container widget_search&quot;&gt;\n				&lt;?php get_search_form(); ?&gt;\n			&lt;/li&gt;\n\n			&lt;li id=&quot;archives&quot; class=&quot;widget-container&quot;&gt;\n				&lt;h3 class=&quot;widget-title&quot;&gt;&lt;?php _e( \'Archives\', \'twentyten\' ); ?&gt;&lt;/h3&gt;\n				&lt;ul&gt;\n					&lt;?php wp_get_archives( \'type=monthly\' ); ?&gt;\n				&lt;/ul&gt;\n			&lt;/li&gt;\n\n			&lt;li id=&quot;meta&quot; class=&quot;widget-container&quot;&gt;\n				&lt;h3 class=&quot;widget-title&quot;&gt;&lt;?php _e( \'Meta\', \'twentyten\' ); ?&gt;&lt;/h3&gt;\n				&lt;ul&gt;\n					&lt;?php wp_register(); ?&gt;\n					&lt;li&gt;&lt;?php wp_loginout(); ?&gt;&lt;/li&gt;\n					&lt;?php wp_meta(); ?&gt;\n				&lt;/ul&gt;\n			&lt;/li&gt;\n\n		&lt;?php endif; // end primary widget area ?&gt;\n			&lt;/ul&gt;\n		&lt;/div&gt;&lt;!-- #primary .widget-area --&gt;\n\n&lt;?php\n	// A second sidebar for widgets, just because.\n	if ( is_active_sidebar( \'secondary-widget-area\' ) ) : ?&gt;\n\n		&lt;div id=&quot;secondary&quot; class=&quot;widget-area&quot; role=&quot;complementary&quot;&gt;\n			&lt;ul class=&quot;xoxo&quot;&gt;\n				&lt;?php dynamic_sidebar( \'secondary-widget-area\' ); ?&gt;\n			&lt;/ul&gt;\n		&lt;/div&gt;&lt;!-- #secondary .widget-area --&gt;\n\n&lt;?php endif; ?&gt;\n</pre>\n<p>عنوان موقعي هو:</p>\n<p><a href=\"http://ds-4u.com/site2/\" rel=\"nofollow\">http://ds-4u.com/site2/</a></p>\n<p>جزاك الله خير الجزاء ، اتمنى اتعلم كيف اذا قمت بها بإذن الله تعالى</p>\n</div>						\n					\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"nasser_wordpress\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:55:\"\n					\n					\n					\n					\n					\n\n					\n\n					\n					\n				\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:51:\"http://www.ar-wp.com/forums/topic/16036/#post-16129\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"رداً على: [إستفسار] كيفيه ازاله الهوامش في الهيدر\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:51:\"http://www.ar-wp.com/forums/topic/16036/#post-16129\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;