(131, '_transient_dash_aa95765b5cc111c56d5993d476b1c2f0', '<div class=\"rss-widget\"><ul><li><a class=\'rsswidget\' href=\'http://www.ar-wp.com/forums/topic/16117/#post-16136\' title=\'في أي سطر .. [&hellip;]\'>رداً على: ما هول حل مشكلة Index of / wp – admin</a></li><li><a class=\'rsswidget\' href=\'http://www.ar-wp.com/forums/topic/16131/#post-16135\' title=\'وعليكم السلام ورحمة الله وبركاته تفضل http://wordpress.org/plugins/tinymce-advanced/ [&hellip;]\'>رداً على: [مشكلة] حذفت إضافة لا أدري ما اسمها !!</a></li><li><a class=\'rsswidget\' href=\'http://www.ar-wp.com/forums/topic/16036/#post-16134\' title=\'لا ادري هل حلت المشكلة . فمظهر الموقع يبدو مناسب … اذا رغبت في اخفاء البياض يمكنك اسستدال اللون بخلفية في الكود السابق اعلاه [&hellip;]\'>رداً على: [إستفسار] كيفيه ازاله الهوامش في الهيدر</a></li><li><a class=\'rsswidget\' href=\'http://www.ar-wp.com/forums/topic/16106/#post-16133\' title=\'اتفضل اخى الطريقة دى نفعت معى ولله الحمد http://www.3nkboot.com//تصدير-او-رفع-قاعدة-البيانات-من-سيرفر-localhost/ [&hellip;]\'>رداً على: [إستفسار] بخصوص انشاء مدونة على السيرفر المحلى ونقلها</a></li><li><a class=\'rsswidget\' href=\'http://www.ar-wp.com/forums/topic/16131/#post-16131\' title=\'السلام عليكم ، كنت قد حذفت عدة إضافات جملة عندما تعطل عمل السلايدر عندي ولم أنتبه للإضافة الخاصة بأزرار التحكم في تنسيق النص في التدوينات ، ولا أعرف ما اسم الإضافة وأحتاجها مرة أخرى بعد حذفها صارت لوحة التنسيق كالمرفقة في الصورة ، ينقصها الكثير . [&hellip;]\'>حذفت إضافة لا أدري ما اسمها !!</a></li></ul></div>', 'no'),
