--
-- Structure de la table `wp_posts`
--

CREATE TABLE `wp_posts` (
  `ID` bigint UNSIGNED NOT NULL,
  `post_author` bigint UNSIGNED NOT NULL DEFAULT '0',
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext NOT NULL,
  `post_title` text NOT NULL,
  `post_excerpt` text NOT NULL,
  `post_status` varchar(20) NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) NOT NULL DEFAULT 'open',
  `post_password` varchar(20) NOT NULL DEFAULT '',
  `post_name` varchar(200) NOT NULL DEFAULT '',
  `to_ping` text NOT NULL,
  `pinged` text NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext NOT NULL,
  `post_parent` bigint UNSIGNED NOT NULL DEFAULT '0',
  `guid` varchar(255) NOT NULL DEFAULT '',
  `menu_order` int NOT NULL DEFAULT '0',
  `post_type` varchar(20) NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) NOT NULL DEFAULT '',
  `comment_count` bigint NOT NULL DEFAULT '0'
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

--
-- Déchargement des données de la table `wp_posts`
--

INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1, 1, '2013-09-24 09:50:31', '2013-09-24 09:50:31', 'مرحباً بك في ووردبريس. هذه تدوينتك الأولى. حررها أو احذفها، ثم ابدأ بالتدوين!\nاذا احتجت لمساعدة يمكنك زيارة موقع <a href=\"http://www.ar-wp.com/\">عرب ووردبريس</a> - الدعم الفني باللغة العربية.\n\n ', 'أهلاً بالعالم !', '', 'publish', 'open', 'open', '', '%d8%a3%d9%87%d9%84%d8%a7-%d8%a8%d8%a7%d9%84%d8%b9%d8%a7%d9%84%d9%85', '', '', '2013-09-24 09:50:31', '2013-09-24 09:50:31', '', 0, 'http://www.ibn-sinaa.com/?p=1', 0, 'post', '', 1),
(2, 1, '2013-09-24 09:50:31', '2013-09-24 09:50:31', 'هنا تشاهد مثال على صفحة. الصفحة تختلف عن التدوينة لأنها تبقى ثابتة وتظهر عادةً في أغلب القوالب ضمن قوائم التصفّح. مفضّل أن تبدأ بإنشاء صفحة جديدة تسميها مثلاً (سيرة ذاتية) أو (من نحن) بحيث تظهر فيها معلومات عامة عن مالك الموقع. لنشاهد مثال على ذلك:\n\n<blockquote>مرحباً! اسمي محمد. وُلدت في فلسطين عام 1980م وأعمل كمبرمج في إحدى الجامعات الرسمية في المملكة العربية السعودية. أقضي يومياً ساعات طويلة أمام شاشة الحاسوب. أحب الشعر وأهوى الخواطر ولدي قطة صغيرة أسميتها \"ميشو\" ... الخ  </blockquote>\n \nمثال آخر:\n \n<blockquote>شركة BVB تأسسّت عام 1909م وهي شركة عالمية متخصّصة بإنتاج المخصبات الزراعية والأسمدة العضوية والمعدنية. مقّر الشركة في ألمانيا ويعمل لدينا أكثر من 88000 موظّف. تتمركز نشاطات الشركة في منطقة وسط أوروبا ... الخ</blockquote>\n \nكمستخدم جديد لنظام ووردبريس عليك التوجّه إلى <a href=\"http://www.ibn-sinaa.com/wp-admin/\">لوحة التحكم</a> لحذف هذه الصفحة وإنشاء صفحة أو صفحات جديدة تكتب فيها ما تراه مناسباً لك. نتمنى لك التوفيق!', 'مثال على صفحة', '', 'publish', 'open', 'open', '', 'مثال-على-صفحة', '', '', '2013-09-24 09:50:31', '2013-09-24 09:50:31', '', 0, 'http://www.ibn-sinaa.com/?page_id=2', 0, 'page', '', 0),
(3, 1, '2013-09-24 12:50:49', '0000-00-00 00:00:00', '', 'مسودة تلقائية', '', 'auto-draft', 'open', 'open', '', '', '', '', '2013-09-24 12:50:49', '0000-00-00 00:00:00', '', 0, 'http://www.ibn-sinaa.com/?p=3', 0, 'post', '', 0),
(4, 1, '2013-09-24 12:51:18', '2013-09-24 09:51:18', '<p>أسمك الكريم (مطلوب)<br />\n    [text* your-name] </p>\n\n<p>بريدك الإلكتروني (مطلوب)<br />\n    [email* your-email] </p>\n\n<p>العنوان<br />\n    [text your-subject] </p>\n\n<p>رسالتك<br />\n    [textarea your-message] </p>\n\n<p>[submit \"إرسال\"]</p>\n[your-subject]\n[your-name] <[your-email]>\nمن: [your-name] <[your-email]>\nالعنوان: [your-subject]\n\nالرسالة:\n[your-message]\n\n--\nThis e-mail was sent from a contact form on تحضير ابن سينا (http://www.ibn-sinaa.com)\nhamada_top@live.com\n\n\n0\n\n[your-subject]\n[your-name] <[your-email]>\nالرسالة:\n[your-message]\n\n--\nThis e-mail was sent from a contact form on تحضير ابن سينا (http://www.ibn-sinaa.com)\n[your-email]\n\n\n0\nتم إرسال الرسالة بنجاح. شكراً\nفشل في إرسال الرسالة. الرجاء المحاولة مجدداً أو مخاطبة المسؤول عن الموقع بطريقة أخرى مثل الفيس بوك أو التويتر.\nحدث خطأ أثناء التحقق. الرجاء التأكد من الحقول ومعاودة الإرسال مجدداً.\nفشل في إرسال الرسالة. الرجاء المحاولة مجدداً أو مخاطبة المسؤول عن الموقع بطريقة أخرى مثل الفيس بوك أو التويتر.\nالرجاء الموافقة على الشروط لإكمال العمليّة.\nالرجاء أكمل الحقول الناقصة', 'استمارة المراسلة 1', '', 'publish', 'open', 'open', '', '%d8%a7%d8%b3%d8%aa%d9%85%d8%a7%d8%b1%d8%a9-%d8%a7%d9%84%d9%85%d8%b1%d8%a7%d8%b3%d9%84%d8%a9-1', '', '', '2013-09-24 12:51:18', '2013-09-24 09:51:18', '', 0, 'http://www.ibn-sinaa.com/?post_type=wpcf7_contact_form&p=4', 0, 'wpcf7_contact_form', '', 0);

